window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7c29236124c88cce"]={"versions": [{"id": "FIG-7c29236124c88cce", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (Ausschnitt des AUTOSAR-M2-Metamodells aus <code>AUTOSAR_TPS_BSWModuleDescriptionTemplate</code>, Kapitel <em>Dependencies of an Implementation</em>).</li>\n<li><strong>Technischer Zweck:</strong> Formale Beschreibung externer Abhängigkeiten einer Modul-Implementierung (<code>BswImplementation</code> bzw. generisch <code>Implementation</code>) von konkreten Datei- und Engineering-Artefakten (z. B. Header-Dateien, statische Bibliotheken, Objektdateien, Generatoren) sowie deren Zuordnung zum jeweiligen Verarbeitungsschritt im Build- und Integrationsprozess.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>DependencyOnArtifact</code></strong> (spezialisiert <code>Identifiable</code>):</li>\n<li>Kapselt die Abhängigkeitsbeziehung einer Implementierung zu einem konkreten Artefakt.</li>\n<li><strong>Attribute:</strong></li>\n<li><code>usage: DependencyUsageEnum [1..*]</code>: Definiert mindestens einen (oder mehrere) Prozessschritte, in denen das referenzierte Artefakt benötigt wird.</li>\n<li><strong>Assoziationen:</strong></li>\n<li>Komposition (<code>1</code>) zu <code>AutosarEngineeringObject</code> über die Rollenbezeichnung <code>+artifactDescriptor</code>. Das Engineering-Objekt ist existenziell an die Dependency gebunden.</li>\n<li><strong><code>AutosarEngineeringObject</code></strong>:</li>\n<li>Konkrete Ausprägung eines Artefakts im AUTOSAR-Engineering-Kontext.</li>\n<li>Spezialisiert die abstrakte Basisklasse <code>EngineeringObject</code>.</li>\n<li><strong><code>EngineeringObject</code></strong> (abstrakt):</li>\n<li>Generischer Deskriptor für Dateien, Dokumente oder Tools im Dateisystem bzw. Versionskontrollsystem.</li>\n<li><strong>Attribute:</strong></li>\n<li><code>category: NameToken [1]</code>: Klassifiziert das Artefakt semantisch (z. B. <code>SWSRC</code>, <code>SWHDR</code>, <code>LIB</code>, <code>TOOL</code>).</li>\n<li><code>domain: NameToken [0..1]</code>: Optionaler Namensraum bzw. Tool-Domäne.</li>\n<li><code>revisionLabel: RevisionLabelString [0..*]</code>: Revisions-, Versions- oder Commit-Tags zur Rückverfolgbarkeit und Konsistenzprüfung.</li>\n<li><code>shortLabel: NameToken [1]</code>: Bezeichner bzw. Datei-/Objektname des Artefakts.</li>\n<li><strong><code>«enumeration» DependencyUsageEnum</code></strong>:</li>\n<li>Wertemenge für den Verwendungszweck des Artefakts:</li>\n<li><code>codegeneration</code>: Artefakt wird während der Modell-/Code-Generierung benötigt (z. B. Generator-Executables, Templates).</li>\n<li><code>compile</code>: Artefakt ist für den Kompilierschritt erforderlich (z. B. C-Header-Dateien <code>.h</code>).</li>\n<li><code>link</code>: Artefakt wird für den Linkervorgang benötigt (z. B. vorkompilierte Object-Dateien <code>.o</code>/<code>.obj</code> oder Archive <code>.a</code>/<code>.lib</code>).</li>\n<li><code>build</code>: Übergeordnete Build-Abhängigkeit (z. B. Makefiles, Build-Skripte, Compiler-Toolchains).</li>\n<li><code>execute</code>: Zur Laufzeit/Emulation erforderlich (z. B. Runtime-DLLs, Host-Test-Tools).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (falls zutreffend)</h4>\n<ul class=\"fig-list\">\n<li><strong>Metamodell-Ebene:</strong> Kein ECU-Laufzeitverhalten; das Diagramm definiert statische Metadaten für die Toolchain.</li>\n<li><strong>Workflow-Reihenfolge der Toolchain (Build-Pipeline):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><em>Generierungsphase (<code>codegeneration</code>):</em> Evaluierung von Templates und Generatoren zur Erzeugung abgeleiteter Quellcodes.</li>\n<li><em>Kompilierphase (<code>compile</code>):</em> Auflösung von Includepfaden anhand der als <code>compile</code> deklarierten Header (<code>category: SWHDR</code>).</li>\n<li><em>Linkphase (<code>link</code>):</em> Bereitstellung von Bibliotheken (<code>category: LIB</code>) und Objektdateien für den Linker.</li>\n<li><em>Gesamtbau (<code>build</code>):</em> Steuerung des Build-Tools (Orchestrierung von Make/CMake/Ninja).</li>\n<li><em>Test/Ausführung (<code>execute</code>):</em> Bereitstellung von Komponenten für Host-Simulation (z. B. SIL) oder Zielsystemausführung.</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSW-Lieferanten & Stack-Entwickler:</strong> Bei der Auslieferung vorkompilierter BSW-Module (z. B. Crypto-Stacks, MCAL als Object-Code/Library) müssen sämtliche zwingend erforderlichen Header und Bibliotheken als <code>DependencyOnArtifact</code> in der <code>BswModuleDescription</code> (<code>arxml</code>) deklariert werden.</li>\n<li><strong>Automatisierte Build-Generierung:</strong> Integrations-Tools (z. B. DaVinci Configurator, EB tresos) nutzen diese Tags (<code>usage</code>), um Makefiles, Include-Directories (<code>-I</code>) und Linker-Flags automatisch und fehlerfrei ohne manuelle Integratoreingriffe zu konfigurieren.</li>\n<li><strong>Versionssperre & Konsistenzprüfung:</strong> Über <code>revisionLabel</code> und <code>shortLabel</code> stellen Build-Prüfskripte sicher, dass exakt zueinander kompatible Header-, Library- und Compiler-Stände verwendet werden. Inkonsistenzen führen zum Abbruch der Integrations-Pipeline vor dem Flashen.</li>\n</ul>"}, {"id": "FIG-59200b300c902f05", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Datentypdiagramm / Enumeration (Ausschnitt des AUTOSAR-M2-Metamodells aus <code>AUTOSAR_TPS_BSWModuleDescriptionTemplate</code>, Kapitel <em>Dependencies of an Implementation</em>).</li>\n<li><strong>Technischer Zweck:</strong> Definition der Enumeration <code>DependencyUsageEnum</code> zur Klassifizierung der Verwendungsphase bzw. des Build-Schritts für Artefakt-Abhängigkeiten einer Modul-Implementierung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>«enumeration» DependencyUsageEnum</code></strong>:</li>\n<li>Wertemenge für den Verwendungszweck des Artefakts im Build- und Integrationsprozess:</li>\n<li><code>codegeneration</code>: Artefakt wird während der Modell-/Code-Generierung benötigt (z. B. Generator-Executables, Templates).</li>\n<li><code>compile</code>: Artefakt ist für den Kompilierschritt erforderlich (z. B. C-Header-Dateien <code>.h</code>).</li>\n<li><code>link</code>: Artefakt wird für den Linkervorgang benötigt (z. B. vorkompilierte Object-Dateien <code>.o</code>/<code>.obj</code> oder Archive <code>.a</code>/<code>.lib</code>).</li>\n<li><code>build</code>: Übergeordnete Build-Abhängigkeit (z. B. Makefiles, Build-Skripte, Compiler-Toolchains).</li>\n<li><code>execute</code>: Zur Laufzeit/Emulation erforderlich (z. B. Runtime-DLLs, Host-Test-Tools).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Metamodell-Ebene:</strong> Kein ECU-Laufzeitverhalten; statische Metadaten für die Werkzeugkette.</li>\n<li><strong>Workflow-Reihenfolge der Toolchain (Build-Pipeline):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><em>Generierungsphase (<code>codegeneration</code>):</em> Evaluierung und Ausführung von Generatoren und Templates zur Quellcodeerzeugung.</li>\n<li><em>Kompilierphase (<code>compile</code>):</em> Auflösung und Einbindung von Header- und Quellcodedateien für den Compiler.</li>\n<li><em>Linkphase (<code>link</code>):</em> Bereitstellung und Einbindung von Objektdateien und statischen Bibliotheken im Linkervorgang.</li>\n<li><em>Gesamtbau (<code>build</code>):</em> Übergeordnete Build-Steuerung und Ausführung von Make-/Build-Skripten.</li>\n<li><em>Test/Ausführung (<code>execute</code>):</em> Bereitstellung von Komponenten zur Ausführung bzw. Simulation auf dem Host- oder Zielsystem.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Verwendungsdeklaration:</strong> Bei der Spezifikation von Artefakt-Abhängigkeiten in Modulbeschreibungen muss der Einsatzzweck über <code>DependencyUsageEnum</code> angegeben werden, um eine korrekte Zuordnung im Build-Prozess zu gewährleisten.</li>\n<li><strong>Phasenabdeckung:</strong> Die Literale decken den vollständigen Integrationszyklus von der Codegenerierung bis zur Ausführung ab; eine unzutreffende Klassifizierung führt zu Fehlern im Integrationsablauf.</li>\n</ul>"}, {"id": "FIG-e96b4cfe3d34fcb8", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (Ausschnitt des AUTOSAR-M2-Metamodells aus <code>AUTOSAR_TPS_BSWModuleDescriptionTemplate</code>, Kapitel <em>Dependencies of an Implementation</em>).</li>\n<li><strong>Technischer Zweck:</strong> Formale Beschreibung externer Abhängigkeiten einer Modul-Implementierung von konkreten Datei- und Engineering-Artefakten (z. B. Header-Dateien, statische Bibliotheken, Objektdateien, Generatoren) sowie deren Zuordnung zum jeweiligen Verarbeitungsschritt im Build- und Integrationsprozess.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>DependencyOnArtifact</code></strong> (spezialisiert <code>Identifiable</code>):</li>\n<li>Kapselt die Abhängigkeitsbeziehung einer Implementierung zu einem konkreten Artefakt.</li>\n<li><strong>Attribute:</strong></li>\n<li><code>usage :DependencyUsageEnum [1..*]</code>: Definiert mindestens einen Prozessschritt, in dem das referenzierte Artefakt benötigt wird.</li>\n<li><strong>Assoziationen:</strong></li>\n<li>Komposition (<code>1</code>) zu <code>AutosarEngineeringObject</code> über die Rollenbezeichnung <code>+artifactDescriptor</code>.</li>\n<li><strong><code>AutosarEngineeringObject</code></strong>:</li>\n<li>Konkrete Ausprägung eines Artefakts im AUTOSAR-Engineering-Kontext.</li>\n<li>Spezialisiert die abstrakte Basisklasse <code>EngineeringObject</code>.</li>\n<li><strong><code>EngineeringObject</code></strong> (abstrakt):</li>\n<li>Generischer Deskriptor für Dateien, Dokumente oder Tools im Dateisystem bzw. Versionskontrollsystem.</li>\n<li><strong>Attribute:</strong></li>\n<li><code>category :NameToken</code>: Klassifiziert das Artefakt semantisch (z. B. <code>SWSRC</code>, <code>SWHDR</code>, <code>LIB</code>, <code>TOOL</code>).</li>\n<li><code>domain :NameToken [0..1]</code>: Optionaler Namensraum bzw. Tool-Domäne.</li>\n<li><code>revisionLabel :RevisionLabelString [0..*]</code>: Revisions-, Versions- oder Commit-Tags zur Rückverfolgbarkeit.</li>\n<li><code>shortLabel :NameToken</code>: Bezeichner bzw. Datei-/Objektname des Artefakts.</li>\n<li><strong><code>«enumeration» DependencyUsageEnum</code></strong>:</li>\n<li>Wertemenge für den Verwendungszweck des Artefakts:</li>\n<li><code>codegeneration</code>: Artefakt wird während der Modell-/Code-Generierung benötigt (z. B. Generator-Executables, Templates).</li>\n<li><code>compile</code>: Artefakt ist für den Kompilierschritt erforderlich (z. B. C-Header-Dateien <code>.h</code>).</li>\n<li><code>link</code>: Artefakt wird für den Linkervorgang benötigt (z. B. vorkompilierte Object-Dateien <code>.o</code>/<code>.obj</code> oder Archive <code>.a</code>/<code>.lib</code>).</li>\n<li><code>build</code>: Übergeordnete Build-Abhängigkeit (z. B. Makefiles, Build-Skripte, Compiler-Toolchains).</li>\n<li><code>execute</code>: Zur Laufzeit/Emulation erforderlich (z. B. Runtime-DLLs, Host-Test-Tools).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Metamodell-Ebene:</strong> Kein ECU-Laufzeitverhalten; das Diagramm definiert statische Metadaten für die Toolchain.</li>\n<li><strong>Workflow-Reihenfolge der Toolchain (Build-Pipeline):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><em>Generierungsphase (<code>codegeneration</code>):</em> Evaluierung von Templates und Generatoren zur Erzeugung abgeleiteter Quellcodes.</li>\n<li><em>Kompilierphase (<code>compile</code>):</em> Auflösung von Includepfaden anhand der als <code>compile</code> deklarierten Header (<code>category: SWHDR</code>).</li>\n<li><em>Linkphase (<code>link</code>):</em> Bereitstellung von Bibliotheken (<code>category: LIB</code>) und Objektdateien für den Linker.</li>\n<li><em>Gesamtbau (<code>build</code>):</em> Steuerung des Build-Tools (Orchestrierung von Make/CMake/Ninja).</li>\n<li><em>Test/Ausführung (<code>execute</code>):</em> Bereitstellung von Komponenten für Host-Simulation (z. B. SIL) oder Zielsystemausführung.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSW-Lieferanten & Stack-Entwickler:</strong> Bei der Bereitstellung von BSW-Modulen müssen alle externen Dateiabhängigkeiten über <code>DependencyOnArtifact</code> formal beschrieben werden. Jede Abhängigkeit bindet über die Kompositionsrolle <code>+artifactDescriptor</code> genau ein <code>AutosarEngineeringObject</code> (Kardinalität <code>1</code>).</li>\n<li><strong>Build-Prozess-Zuordnung:</strong> Über das Attribut <code>usage</code> muss jedem Artefakt mindestens eine Verwendungsphase zugeordnet sein, damit Integrationswerkzeuge Quell-, Header- oder Bibliotheksdateien der richtigen Verarbeitungsstufe zuführen können.</li>\n</ul>"}, {"id": "FIG-2619b303b34073bd", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (Ausschnitt des AUTOSAR-M2-Metamodells aus <code>AUTOSAR_TPS_BSWModuleDescriptionTemplate</code>, Kapitel <em>Dependencies of an Implementation</em>).</li>\n<li><strong>Technischer Zweck:</strong> Formale Beschreibung externer Abhängigkeiten einer Modul-Implementierung von konkreten Datei- und Engineering-Artefakten (z. B. Header-Dateien, statische Bibliotheken, Objektdateien, Generatoren) sowie deren Zuordnung zum jeweiligen Verarbeitungsschritt im Build- und Integrationsprozess.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>DependencyOnArtifact</code></strong> (spezialisiert <code>Identifiable</code>):</li>\n<li>Kapselt die Abhängigkeitsbeziehung einer Implementierung zu einem konkreten Artefakt.</li>\n<li><strong>Attribute:</strong></li>\n<li><code>usage :DependencyUsageEnum [1..*]</code>: Definiert mindestens einen Prozessschritt, in dem das referenzierte Artefakt benötigt wird.</li>\n<li><strong>Assoziationen:</strong></li>\n<li>Komposition (<code>1</code>) zu <code>AutosarEngineeringObject</code> über die Rollenbezeichnung <code>+artifactDescriptor</code>.</li>\n<li><strong><code>AutosarEngineeringObject</code></strong>:</li>\n<li>Konkrete Ausprägung eines Artefakts im AUTOSAR-Engineering-Kontext.</li>\n<li>Spezialisiert die abstrakte Basisklasse <code>EngineeringObject</code>.</li>\n<li><strong><code>EngineeringObject</code></strong> (abstrakt):</li>\n<li>Generischer Deskriptor für Dateien, Dokumente oder Tools im Dateisystem bzw. Versionskontrollsystem.</li>\n<li><strong>Attribute:</strong></li>\n<li><code>category :NameToken</code>: Klassifiziert das Artefakt semantisch (z. B. <code>SWSRC</code>, <code>SWHDR</code>, <code>LIB</code>, <code>TOOL</code>).</li>\n<li><code>domain :NameToken [0..1]</code>: Optionaler Namensraum bzw. Tool-Domäne.</li>\n<li><code>revisionLabel :RevisionLabelString [0..*]</code>: Revisions-, Versions- oder Commit-Tags zur Rückverfolgbarkeit.</li>\n<li><code>shortLabel :NameToken</code>: Bezeichner bzw. Datei-/Objektname des Artefakts.</li>\n<li><strong><code>«enumeration» DependencyUsageEnum</code></strong>:</li>\n<li>Wertemenge für den Verwendungszweck des Artefakts:</li>\n<li><code>codegeneration</code>: Artefakt wird während der Modell-/Code-Generierung benötigt (z. B. Generator-Executables, Templates).</li>\n<li><code>compile</code>: Artefakt ist für den Kompilierschritt erforderlich (z. B. C-Header-Dateien <code>.h</code>).</li>\n<li><code>link</code>: Artefakt wird für den Linkervorgang benötigt (z. B. vorkompilierte Object-Dateien <code>.o</code>/<code>.obj</code> oder Archive <code>.a</code>/<code>.lib</code>).</li>\n<li><code>build</code>: Übergeordnete Build-Abhängigkeit (z. B. Makefiles, Build-Skripte, Compiler-Toolchains).</li>\n<li><code>execute</code>: Zur Laufzeit/Emulation erforderlich (z. B. Runtime-DLLs, Host-Test-Tools).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Metamodell-Ebene:</strong> Kein ECU-Laufzeitverhalten; das Diagramm definiert statische Metadaten für die Toolchain.</li>\n<li><strong>Workflow-Reihenfolge der Toolchain (Build-Pipeline):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><em>Generierungsphase (<code>codegeneration</code>):</em> Evaluierung von Templates und Generatoren zur Erzeugung abgeleiteter Quellcodes.</li>\n<li><em>Kompilierphase (<code>compile</code>):</em> Auflösung von Includepfaden anhand der als <code>compile</code> deklarierten Header (<code>category: SWHDR</code>).</li>\n<li><em>Linkphase (<code>link</code>):</em> Bereitstellung von Bibliotheken (<code>category: LIB</code>) und Objektdateien für den Linker.</li>\n<li><em>Gesamtbau (<code>build</code>):</em> Steuerung des Build-Tools (Orchestrierung von Make/CMake/Ninja).</li>\n<li><em>Test/Ausführung (<code>execute</code>):</em> Bereitstellung von Komponenten für Host-Simulation (z. B. SIL) oder Zielsystemausführung.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSW-Lieferanten & Stack-Entwickler:</strong> Bei der Bereitstellung von BSW-Modulen müssen alle externen Dateiabhängigkeiten über <code>DependencyOnArtifact</code> formal beschrieben werden. Jede Abhängigkeit bindet über die Kompositionsrolle <code>+artifactDescriptor</code> genau ein <code>AutosarEngineeringObject</code> (Kardinalität <code>1</code>).</li>\n<li><strong>Build-Prozess-Zuordnung:</strong> Über das Attribut <code>usage</code> muss jedem Artefakt mindestens eine Verwendungsphase zugeordnet sein, damit Integrationswerkzeuge Quell-, Header- oder Bibliotheksdateien der richtigen Verarbeitungsstufe zuführen können.</li>\n</ul>"}, {"id": "FIG-f74081d640bf5ff6", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (Ausschnitt des AUTOSAR-M2-Metamodells aus <code>AUTOSAR_TPS_BSWModuleDescriptionTemplate</code>, Kapitel <em>Dependencies of an Implementation</em>).</li>\n<li><strong>Technischer Zweck:</strong> Formale Beschreibung externer Abhängigkeiten einer Modul-Implementierung von konkreten Datei- und Engineering-Artefakten (z. B. Header-Dateien, statische Bibliotheken, Objektdateien, Generatoren) sowie deren Zuordnung zum jeweiligen Verarbeitungsschritt im Build- und Integrationsprozess.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>DependencyOnArtifact</code></strong> (spezialisiert <code>Identifiable</code>):</li>\n<li>Kapselt die Abhängigkeitsbeziehung einer Implementierung zu einem konkreten Artefakt.</li>\n<li><strong>Attribute:</strong></li>\n<li><code>usage :DependencyUsageEnum [1..*]</code>: Definiert mindestens einen Prozessschritt, in dem das referenzierte Artefakt benötigt wird.</li>\n<li><strong>Assoziationen:</strong></li>\n<li>Komposition (<code>1</code>) zu <code>AutosarEngineeringObject</code> über die Rollenbezeichnung <code>+artifactDescriptor</code>.</li>\n<li><strong><code>AutosarEngineeringObject</code></strong>:</li>\n<li>Konkrete Ausprägung eines Artefakts im AUTOSAR-Engineering-Kontext.</li>\n<li>Spezialisiert die abstrakte Basisklasse <code>EngineeringObject</code>.</li>\n<li><strong><code>EngineeringObject</code></strong> (abstrakt):</li>\n<li>Generischer Deskriptor für Dateien, Dokumente oder Tools im Dateisystem bzw. Versionskontrollsystem.</li>\n<li><strong>Attribute:</strong></li>\n<li><code>category :NameToken</code>: Klassifiziert das Artefakt semantisch (z. B. <code>SWSRC</code>, <code>SWHDR</code>, <code>LIB</code>, <code>TOOL</code>).</li>\n<li><code>domain :NameToken [0..1]</code>: Optionaler Namensraum bzw. Tool-Domäne.</li>\n<li><code>revisionLabel :RevisionLabelString [0..*]</code>: Revisions-, Versions- oder Commit-Tags zur Rückverfolgbarkeit.</li>\n<li><code>shortLabel :NameToken</code>: Bezeichner bzw. Datei-/Objektname des Artefakts.</li>\n<li><strong><code>«enumeration» DependencyUsageEnum</code></strong>:</li>\n<li>Wertemenge für den Verwendungszweck des Artefakts:</li>\n<li><code>codegeneration</code>: Artefakt wird während der Modell-/Code-Generierung benötigt (z. B. Generator-Executables, Templates).</li>\n<li><code>compile</code>: Artefakt ist für den Kompilierschritt erforderlich (z. B. C-Header-Dateien <code>.h</code>).</li>\n<li><code>link</code>: Artefakt wird für den Linkervorgang benötigt (z. B. vorkompilierte Object-Dateien <code>.o</code>/<code>.obj</code> oder Archive <code>.a</code>/<code>.lib</code>).</li>\n<li><code>build</code>: Übergeordnete Build-Abhängigkeit (z. B. Makefiles, Build-Skripte, Compiler-Toolchains).</li>\n<li><code>execute</code>: Zur Laufzeit/Emulation erforderlich (z. B. Runtime-DLLs, Host-Test-Tools).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Metamodell-Ebene:</strong> Kein ECU-Laufzeitverhalten; das Diagramm definiert statische Metadaten für die Toolchain.</li>\n<li><strong>Workflow-Reihenfolge der Toolchain (Build-Pipeline):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><em>Generierungsphase (<code>codegeneration</code>):</em> Evaluierung von Templates und Generatoren zur Erzeugung abgeleiteter Quellcodes.</li>\n<li><em>Kompilierphase (<code>compile</code>):</em> Auflösung von Includepfaden anhand der als <code>compile</code> deklarierten Header (<code>category: SWHDR</code>).</li>\n<li><em>Linkphase (<code>link</code>):</em> Bereitstellung von Bibliotheken (<code>category: LIB</code>) und Objektdateien für den Linker.</li>\n<li><em>Gesamtbau (<code>build</code>):</em> Steuerung des Build-Tools (Orchestrierung von Make/CMake/Ninja).</li>\n<li><em>Test/Ausführung (<code>execute</code>):</em> Bereitstellung von Komponenten für Host-Simulation (z. B. SIL) oder Zielsystemausführung.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSW-Lieferanten & Stack-Entwickler:</strong> Bei der Bereitstellung von BSW-Modulen müssen alle externen Dateiabhängigkeiten über <code>DependencyOnArtifact</code> formal beschrieben werden. Jede Abhängigkeit bindet über die Kompositionsrolle <code>+artifactDescriptor</code> genau ein <code>AutosarEngineeringObject</code> (Kardinalität <code>1</code>).</li>\n<li><strong>Build-Prozess-Zuordnung:</strong> Über das Attribut <code>usage</code> muss jedem Artefakt mindestens eine Verwendungsphase zugeordnet sein, damit Integrationswerkzeuge Quell-, Header- oder Bibliotheksdateien der richtigen Verarbeitungsstufe zuführen können.</li>\n</ul>"}, {"id": "FIG-c076c535c4df3271", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (Ausschnitt des AUTOSAR-M2-Metamodells aus <code>AUTOSAR_TPS_BSWModuleDescriptionTemplate</code>, Kapitel <em>Dependencies of an Implementation</em>).</li>\n<li><strong>Technischer Zweck:</strong> Formale Beschreibung externer Abhängigkeiten einer Modul-Implementierung von konkreten Datei- und Engineering-Artefakten (z. B. Header-Dateien, statische Bibliotheken, Objektdateien, Generatoren) sowie deren Zuordnung zum jeweiligen Verarbeitungsschritt im Build- und Integrationsprozess.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>DependencyOnArtifact</code></strong> (spezialisiert <code>Identifiable</code>):</li>\n<li>Kapselt die Abhängigkeitsbeziehung einer Implementierung zu einem konkreten Artefakt.</li>\n<li><strong>Attribute:</strong></li>\n<li><code>usage: DependencyUsageEnum [1..*]</code>: Definiert mindestens einen Prozessschritt, in dem das referenzierte Artefakt benötigt wird.</li>\n<li><strong>Assoziationen:</strong></li>\n<li>Komposition (<code>0..1</code>) zu <code>AutosarEngineeringObject</code> über die Rollenbezeichnung <code>+artifactDescriptor</code>.</li>\n<li><strong><code>AutosarEngineeringObject</code></strong>:</li>\n<li>Konkrete Ausprägung eines Artefakts im AUTOSAR-Engineering-Kontext.</li>\n<li>Spezialisiert die abstrakte Basisklasse <code>EngineeringObject</code>.</li>\n<li><strong><code>EngineeringObject</code></strong> (abstrakt):</li>\n<li>Generischer Deskriptor für Dateien, Dokumente oder Tools im Dateisystem bzw. Versionskontrollsystem.</li>\n<li><strong>Attribute:</strong></li>\n<li><code>category: NameToken</code>: Klassifiziert das Artefakt semantisch (z. B. <code>SWSRC</code>, <code>SWHDR</code>, <code>LIB</code>, <code>TOOL</code>).</li>\n<li><code>domain: NameToken [0..1]</code>: Optionaler Namensraum bzw. Tool-Domäne.</li>\n<li><code>revisionLabel: RevisionLabelString [0..*]</code>: Revisions-, Versions- oder Commit-Tags zur Rückverfolgbarkeit.</li>\n<li><code>shortLabel: NameToken</code>: Bezeichner bzw. Datei-/Objektname des Artefakts.</li>\n<li><strong><code>«enumeration» DependencyUsageEnum</code></strong>:</li>\n<li>Wertemenge für den Verwendungszweck des Artefakts:</li>\n<li><code>codegeneration</code>: Artefakt wird während der Modell-/Code-Generierung benötigt (z. B. Generator-Executables, Templates).</li>\n<li><code>compile</code>: Artefakt ist für den Kompilierschritt erforderlich (z. B. C-Header-Dateien <code>.h</code>).</li>\n<li><code>link</code>: Artefakt wird für den Linkervorgang benötigt (z. B. vorkompilierte Object-Dateien <code>.o</code>/<code>.obj</code> oder Archive <code>.a</code>/<code>.lib</code>).</li>\n<li><code>build</code>: Übergeordnete Build-Abhängigkeit (z. B. Makefiles, Build-Skripte, Compiler-Toolchains).</li>\n<li><code>execute</code>: Zur Laufzeit/Emulation erforderlich (z. B. Runtime-DLLs, Host-Test-Tools).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Metamodell-Ebene:</strong> Kein ECU-Laufzeitverhalten; das Diagramm definiert statische Metadaten für die Toolchain.</li>\n<li><strong>Workflow-Reihenfolge der Toolchain (Build-Pipeline):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><em>Generierungsphase (<code>codegeneration</code>):</em> Evaluierung von Templates und Generatoren zur Erzeugung abgeleiteter Quellcodes.</li>\n<li><em>Kompilierphase (<code>compile</code>):</em> Auflösung von Includepfaden anhand der als <code>compile</code> deklarierten Header (<code>category: SWHDR</code>).</li>\n<li><em>Linkphase (<code>link</code>):</em> Bereitstellung von Bibliotheken (<code>category: LIB</code>) und Objektdateien für den Linker.</li>\n<li><em>Gesamtbau (<code>build</code>):</em> Steuerung des Build-Tools (Orchestrierung von Make/CMake/Ninja).</li>\n<li><em>Test/Ausführung (<code>execute</code>):</em> Bereitstellung von Komponenten für Host-Simulation (z. B. SIL) oder Zielsystemausführung.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSW-Lieferanten & Stack-Entwickler:</strong> Bei der Bereitstellung von BSW-Modulen können externe Dateiabhängigkeiten über <code>DependencyOnArtifact</code> formal beschrieben werden. Die Einbindung eines konkreten <code>AutosarEngineeringObject</code> über die Kompositionsrolle <code>+artifactDescriptor</code> ist optional (Kardinalität <code>0..1</code>).</li>\n<li><strong>Build-Prozess-Zuordnung:</strong> Über das Attribut <code>usage</code> muss jedem Artefakt mindestens eine Verwendungsphase zugeordnet sein, damit Integrationswerkzeuge Quell-, Header- oder Bibliotheksdateien der richtigen Verarbeitungsstufe zuführen können.</li>\n</ul>"}, {"id": "FIG-e0bc77cfdfe79fd3", "releases": ["R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Datentypdiagramm / Enumeration (Ausschnitt des AUTOSAR-M2-Metamodells aus <code>AUTOSAR_TPS_BSWModuleDescriptionTemplate</code>, Kapitel <em>Dependencies of an Implementation</em>).</li>\n<li><strong>Technischer Zweck:</strong> Definition der Enumeration <code>DependencyUsageEnum</code> zur Klassifizierung der Verwendungsphase bzw. des Build-Schritts für Artefakt-Abhängigkeiten einer Modul-Implementierung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>«enumeration» DependencyUsageEnum</code></strong>:</li>\n<li>Wertemenge für den Verwendungszweck des Artefakts im Build- und Integrationsprozess:</li>\n<li><code>codegeneration</code>: Artefakt wird während der Modell-/Code-Generierung benötigt (z. B. Generator-Executables, Templates).</li>\n<li><code>compile</code>: Artefakt ist für den Kompilierschritt erforderlich (z. B. C-Header-Dateien <code>.h</code>).</li>\n<li><code>link</code>: Artefakt wird für den Linkervorgang benötigt (z. B. vorkompilierte Object-Dateien <code>.o</code>/<code>.obj</code> oder Archive <code>.a</code>/<code>.lib</code>).</li>\n<li><code>build</code>: Übergeordnete Build-Abhängigkeit (z. B. Makefiles, Build-Skripte, Compiler-Toolchains).</li>\n<li><code>execute</code>: Zur Laufzeit/Emulation erforderlich (z. B. Runtime-DLLs, Host-Test-Tools).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Metamodell-Ebene:</strong> Kein ECU-Laufzeitverhalten; statische Metadaten für die Werkzeugkette.</li>\n<li><strong>Workflow-Reihenfolge der Toolchain (Build-Pipeline):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><em>Generierungsphase (<code>codegeneration</code>):</em> Evaluierung und Ausführung von Generatoren und Templates zur Quellcodeerzeugung.</li>\n<li><em>Kompilierphase (<code>compile</code>):</em> Auflösung und Einbindung von Header- und Quellcodedateien für den Compiler.</li>\n<li><em>Linkphase (<code>link</code>):</em> Bereitstellung und Einbindung von Objektdateien und statischen Bibliotheken im Linkervorgang.</li>\n<li><em>Gesamtbau (<code>build</code>):</em> Übergeordnete Build-Steuerung und Ausführung von Make-/Build-Skripten.</li>\n<li><em>Test/Ausführung (<code>execute</code>):</em> Bereitstellung von Komponenten zur Ausführung bzw. Simulation auf dem Host- oder Zielsystem.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Verwendungsdeklaration:</strong> Bei der Spezifikation von Artefakt-Abhängigkeiten in Modulbeschreibungen muss der Einsatzzweck über <code>DependencyUsageEnum</code> angegeben werden, um eine korrekte Zuordnung im Build-Prozess zu gewährleisten.</li>\n<li><strong>Phasenabdeckung:</strong> Die Literale decken den vollständigen Integrationszyklus von der Codegenerierung bis zur Ausführung ab; eine unzutreffende Klassifizierung führt zu Fehlern im Integrationsablauf.</li>\n</ul>"}, {"id": "FIG-8d81be6fbafc0bcd", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (Ausschnitt des AUTOSAR-M2-Metamodells aus <code>AUTOSAR_TPS_BSWModuleDescriptionTemplate</code>, Kapitel <em>Dependencies of an Implementation</em>).</li>\n<li><strong>Technischer Zweck:</strong> Metamodellierung der Artefakt-Abhängigkeiten einer Modul-Implementierung über <code>DependencyOnArtifact</code>, Verknüpfung mit dem Artefakt-Deskriptor <code>AutosarEngineeringObject</code> (Spezialisierung von <code>EngineeringObject</code>) und Spezifikation der Build- und Verwendungsphasen über <code>DependencyUsageEnum</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>DependencyOnArtifact</code> (<code>Identifiable</code>):</strong></li>\n<li>Repräsentiert die Abhängigkeit einer Implementierung von einem externen Software-Artefakt.</li>\n<li>Attribute:</li>\n<li><code>+ usage: DependencyUsageEnum [0..*]</code>: Phasen bzw. Schritte im Erstellungsprozess, in denen das Artefakt benötigt wird.</li>\n<li>Assoziationen:</li>\n<li><code>+artifactDescriptor</code>: Komposition mit Kardinalität <code>0..1</code> auf <code>AutosarEngineeringObject</code>.</li>\n<li><strong><code>AutosarEngineeringObject</code>:</strong></li>\n<li>Konkrete Ausprägung eines AUTOSAR-Artefakt-Deskriptors.</li>\n<li>Spezialisiert <code>EngineeringObject</code> via Generalisierungsbeziehung.</li>\n<li><strong><code>EngineeringObject</code> (abstrakt):</strong></li>\n<li>Allgemeine Basisklasse zur Identifikation, Versionierung und Einordnung von Entwicklungsartefakten.</li>\n<li>Attribute:</li>\n<li><code>+ category: NameToken</code>: Kategorie bzw. Art des Artefakts.</li>\n<li><code>+ domain: NameToken [0..1]</code>: Optionaler Fach- oder Anwendungsbereich.</li>\n<li><code>+ revisionLabel: RevisionLabelString [0..*]</code>: Revisions- bzw. Versionskennzeichnung.</li>\n<li><code>+ shortLabel: NameToken</code>: Eindeutiger Kurzbezeichner des Artefakts.</li>\n<li><strong><code>«enumeration» DependencyUsageEnum</code>:</strong></li>\n<li>Aufzählungstyp für die Verwendungsphasen (<code>literals</code>):</li>\n<li><code>codegeneration</code>: Verwendung während der Quellcode- oder Modellgenerierung.</li>\n<li><code>compile</code>: Verwendung beim Kompiliervorgang (z. B. Header-Dateien).</li>\n<li><code>link</code>: Verwendung während des Linkens (z. B. Objektdateien, statische Bibliotheken).</li>\n<li><code>build</code>: Verwendung durch übergeordnete Build-Werkzeuge und Make-Skripte.</li>\n<li><code>execute</code>: Verwendung zur Laufzeit, Emulation oder Simulation.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Metamodell-Ebene:</strong> Statische Metadatenstruktur; kein ECU-Laufzeitverhalten.</li>\n<li><strong>Artefakt- und Phasenauflösung in der Toolchain:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><em>Abhängigkeitsauflösung:</em> Werkzeuge werten <code>DependencyOnArtifact</code> aus und identifizieren das physische Artefakt über <code>artifactDescriptor</code> (<code>AutosarEngineeringObject</code>) anhand dessen Attributen (<code>shortLabel</code>, <code>category</code>, <code>domain</code>, <code>revisionLabel</code>).</li>\n<li><em>Phasenbezogene Bereitstellung (<code>usage</code>):</em></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>codegeneration</code>: Bereitstellung von Modellvorlagen und Generatoren vor der Codeerzeugung.</li>\n<li><code>compile</code>: Bereitstellung von Header-Dateien und Schnittstellen für den Compiler.</li>\n<li><code>link</code>: Einbindung kompilierter Objekt- und Bibliotheksdateien in den Linkeraufruf.</li>\n<li><code>build</code>: Bereitstellung von Steuerungsskripten für das übergeordnete Build-System.</li>\n<li><code>execute</code>: Bereitstellung ausführbarer Artefakte zur Ausführung oder Simulation auf Ziel- und Hostsystemen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Identifizierbarkeit:</strong> <code>DependencyOnArtifact</code> ist als <code>Identifiable</code> spezialisiert und besitzt die entsprechenden Standardeigenschaften zur Identifikation und Modellreferenzierung.</li>\n<li><strong>Artefakt-Deskriptor:</strong> Über die Kompositionsrolle <code>+artifactDescriptor</code> kann einer Abhängigkeit maximal ein <code>AutosarEngineeringObject</code> (<code>0..1</code>) fest zugeordnet werden.</li>\n<li><strong>Phasen-Multiplizität:</strong> Das Attribut <code>usage</code> ist mit Multiplizität <code>[0..*]</code> deklariert; ein Artefakt kann für mehrere Erstellungsphasen gleichzeitig oder ohne explizite Phaseneinschränkung spezifiziert werden.</li>\n<li><strong>Artefakt-Metadaten:</strong> Durch Vererbung von <code>EngineeringObject</code> sind <code>category</code> und <code>shortLabel</code> Pflichtattribute zur Beschreibung des Artefakts, während <code>domain</code> (<code>[0..1]</code>) optional ist und <code>revisionLabel</code> (<code>[0..*]</code>) mehrfach belegt werden kann.</li>\n</ul>"}, {"id": "FIG-5cbff51039b2f8a8", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (Ausschnitt des AUTOSAR-M2-Metamodells aus <code>AUTOSAR_TPS_BSWModuleDescriptionTemplate</code>, Kapitel <em>Dependencies of an Implementation</em>).</li>\n<li><strong>Technischer Zweck:</strong> Metamodellierung der Artefakt-Abhängigkeiten einer Modul-Implementierung über <code>DependencyOnArtifact</code>, Verknüpfung mit dem Artefakt-Deskriptor <code>AutosarEngineeringObject</code> (Spezialisierung von <code>EngineeringObject</code>) und Spezifikation der Build- und Verwendungsphasen über <code>DependencyUsageEnum</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>DependencyOnArtifact</code> (<code>Identifiable</code>):</strong></li>\n<li>Repräsentiert die Abhängigkeit einer Implementierung von einem externen Software-Artefakt.</li>\n<li>Attribute:</li>\n<li><code>+ usage: DependencyUsageEnum [0..*]</code>: Phasen bzw. Schritte im Erstellungsprozess, in denen das Artefakt benötigt wird.</li>\n<li>Assoziationen:</li>\n<li><code>+artifactDescriptor</code>: Komposition mit Kardinalität <code>0..1</code> auf <code>AutosarEngineeringObject</code>.</li>\n<li><strong><code>AutosarEngineeringObject</code>:</strong></li>\n<li>Konkrete Ausprägung eines AUTOSAR-Artefakt-Deskriptors.</li>\n<li>Spezialisiert <code>EngineeringObject</code> via Generalisierungsbeziehung.</li>\n<li><strong><code>EngineeringObject</code> (abstrakt):</strong></li>\n<li>Allgemeine Basisklasse zur Identifikation, Versionierung und Einordnung von Entwicklungsartefakten.</li>\n<li>Attribute:</li>\n<li><code>+ category: NameToken</code>: Kategorie bzw. Art des Artefakts.</li>\n<li><code>+ domain: NameToken [0..1]</code>: Optionaler Fach- oder Anwendungsbereich.</li>\n<li><code>+ revisionLabel: RevisionLabelString [0..*]</code>: Revisions- bzw. Versionskennzeichnung.</li>\n<li><code>+ shortLabel: NameToken</code>: Eindeutiger Kurzbezeichner des Artefakts.</li>\n<li><strong><code>«enumeration» DependencyUsageEnum</code>:</strong></li>\n<li>Aufzählungstyp für die Verwendungsphasen (<code>literals</code>):</li>\n<li><code>codegeneration</code>: Verwendung während der Quellcode- oder Modellgenerierung.</li>\n<li><code>compile</code>: Verwendung beim Kompiliervorgang (z. B. Header-Dateien).</li>\n<li><code>link</code>: Verwendung während des Linkens (z. B. Objektdateien, statische Bibliotheken).</li>\n<li><code>build</code>: Verwendung durch übergeordnete Build-Werkzeuge und Make-Skripte.</li>\n<li><code>execute</code>: Verwendung zur Laufzeit, Emulation oder Simulation.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Metamodell-Ebene:</strong> Statische Metadatenstruktur; kein ECU-Laufzeitverhalten.</li>\n<li><strong>Artefakt- und Phasenauflösung in der Toolchain:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><em>Abhängigkeitsauflösung:</em> Werkzeuge werten <code>DependencyOnArtifact</code> aus und identifizieren das physische Artefakt über <code>artifactDescriptor</code> (<code>AutosarEngineeringObject</code>) anhand dessen Attributen (<code>shortLabel</code>, <code>category</code>, <code>domain</code>, <code>revisionLabel</code>).</li>\n<li><em>Phasenbezogene Bereitstellung (<code>usage</code>):</em></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>codegeneration</code>: Bereitstellung von Modellvorlagen und Generatoren vor der Codeerzeugung.</li>\n<li><code>compile</code>: Bereitstellung von Header-Dateien und Schnittstellen für den Compiler.</li>\n<li><code>link</code>: Einbindung kompilierter Objekt- und Bibliotheksdateien in den Linkeraufruf.</li>\n<li><code>build</code>: Bereitstellung von Steuerungsskripten für das übergeordnete Build-System.</li>\n<li><code>execute</code>: Bereitstellung ausführbarer Artefakte zur Ausführung oder Simulation auf Ziel- und Hostsystemen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Identifizierbarkeit:</strong> <code>DependencyOnArtifact</code> ist als <code>Identifiable</code> spezialisiert und besitzt die entsprechenden Standardeigenschaften zur Identifikation und Modellreferenzierung.</li>\n<li><strong>Artefakt-Deskriptor:</strong> Über die Kompositionsrolle <code>+artifactDescriptor</code> kann einer Abhängigkeit maximal ein <code>AutosarEngineeringObject</code> (<code>0..1</code>) fest zugeordnet werden.</li>\n<li><strong>Phasen-Multiplizität:</strong> Das Attribut <code>usage</code> ist mit Multiplizität <code>[0..*]</code> deklariert; ein Artefakt kann für mehrere Erstellungsphasen gleichzeitig oder ohne explizite Phaseneinschränkung spezifiziert werden.</li>\n<li><strong>Artefakt-Metadaten:</strong> Durch Vererbung von <code>EngineeringObject</code> sind <code>category</code> und <code>shortLabel</code> Pflichtattribute zur Beschreibung des Artefakts, während <code>domain</code> (<code>[0..1]</code>) optional ist und <code>revisionLabel</code> (<code>[0..*]</code>) mehrfach belegt werden kann.</li>\n</ul>"}], "trans": [{"from": "FIG-7c29236124c88cce", "to": "FIG-59200b300c902f05", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Entfall der Klassen <code>DependencyOnArtifact</code>, <code>AutosarEngineeringObject</code> und <code>EngineeringObject</code> samt Attributen (<code>usage</code>, <code>category</code>, <code>domain</code>, <code>revisionLabel</code>, <code>shortLabel</code>).</li>\n<li>Entfall der Kompositionsbeziehung <code>artifactDescriptor</code> (Multiplizität <code>1</code>) sowie der Generalisierungsbeziehungen zu <code>Identifiable</code> und <code>EngineeringObject</code>.</li>\n<li>Das Schaubild beschränkt sich auf die Darstellung der Enumeration <code>DependencyUsageEnum</code>.</li>\n</ul>"}, {"from": "FIG-59200b300c902f05", "to": "FIG-e96b4cfe3d34fcb8", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Wiedereinführung der Klassen <code>DependencyOnArtifact</code> (spezialisiert <code>Identifiable</code>, Attribut <code>usage :DependencyUsageEnum [1..*]</code>), <code>AutosarEngineeringObject</code> und <code>EngineeringObject</code> (Attribute <code>category</code>, <code>domain</code>, <code>revisionLabel</code>, <code>shortLabel</code>).</li>\n<li>Wiedereinführung der Komposition <code>artifactDescriptor</code> mit Multiplizität <code>1</code> zwischen <code>DependencyOnArtifact</code> und <code>AutosarEngineeringObject</code> sowie der Generalisierung von <code>AutosarEngineeringObject</code> zu <code>EngineeringObject</code>.</li>\n<li>Geändertes Diagrammlayout: <code>EngineeringObject</code> ist nun rechts neben <code>DependencyOnArtifact</code> angeordnet, <code>AutosarEngineeringObject</code> spannt sich darunter über die gesamte Breite.</li>\n<li>Schreibweise der Attributtypen mit führendem Leerzeichen vor dem Doppelpunkt formatiert (<code>usage :DependencyUsageEnum [1..*]</code>, <code>category :NameToken</code> etc.).</li>\n</ul>"}, {"from": "FIG-e96b4cfe3d34fcb8", "to": "FIG-2619b303b34073bd", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Vereinheitlichung der Typformatierung bei Attributdefinitionen: Leerzeichen vor dem Doppelpunkt entfernt und hinter den Doppelpunkt gesetzt (<code>usage: DependencyUsageEnum [1..<em>]</code>, <code>category: NameToken</code>, <code>domain: NameToken [0..1]</code>, <code>revisionLabel: RevisionLabelString [0..</em>]</code>, <code>shortLabel: NameToken</code>).</li>\n</ul>"}, {"from": "FIG-2619b303b34073bd", "to": "FIG-f74081d640bf5ff6", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-f74081d640bf5ff6", "to": "FIG-c076c535c4df3271", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Multiplizität der Kompositionsrolle <code>+artifactDescriptor</code> zwischen <code>DependencyOnArtifact</code> und <code>AutosarEngineeringObject</code> von <code>1</code> auf <code>0..1</code> gelockert.</li>\n</ul>"}, {"from": "FIG-c076c535c4df3271", "to": "FIG-e0bc77cfdfe79fd3", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Entfall der Klassen <code>DependencyOnArtifact</code>, <code>AutosarEngineeringObject</code> und <code>EngineeringObject</code> sowie deren Attributen und Assoziationen (<code>+artifactDescriptor 0..1</code>, Generalisierungen).</li>\n<li>Das Schaubild beschränkt sich auf die Darstellung der Enumeration <code>DependencyUsageEnum</code>.</li>\n</ul>"}, {"from": "FIG-e0bc77cfdfe79fd3", "to": "FIG-8d81be6fbafc0bcd", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>DependencyOnArtifact</code>: Klasse ergänzt (als <code>Identifiable</code> gekennzeichnet) mit Attribut <code>+ usage: DependencyUsageEnum [0..*]</code>.</li>\n<li><code>AutosarEngineeringObject</code>: Klasse ergänzt als Ziel der Kompositionsbeziehung <code>+artifactDescriptor</code> (Kardinalität <code>0..1</code>) ausgehend von <code>DependencyOnArtifact</code>.</li>\n<li><code>EngineeringObject</code>: Abstrakte Basisklasse ergänzt mit den Attributen <code>+ category: NameToken</code>, <code>+ domain: NameToken [0..1]</code>, <code>+ revisionLabel: RevisionLabelString [0..*]</code> und <code>+ shortLabel: NameToken</code>; dient als Generalisierung für <code>AutosarEngineeringObject</code>.</li>\n<li><code>DependencyUsageEnum</code>: Ergänzung der Trennbezeichnung <code>literals</code> über der Literalaufzählung.</li>\n</ul>"}, {"from": "FIG-8d81be6fbafc0bcd", "to": "FIG-5cbff51039b2f8a8", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
